import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address nonOwner, uint256 value, address target) public {
        vm.assume(nonOwner != address(this)); // owner is setUp's address (Test contract)
        vm.assume(nonOwner != address(0));
        vm.assume(target != address(c));

        uint256 countBefore = c.depositsCount();

        vm.deal(nonOwner, value);
        vm.prank(nonOwner);
        (bool success, ) = address(c).call{value: value}("");
        if (success) {
            // only reachable if fallback succeeded (can happen with enough gas etc.)
            // In reference, nonOwner can trigger fallback because fallback has no access control,
            // so depositsCount always increments. In buggy, modifier is inverted but fallback has no modifier.
            // The difference is in sendMoney which uses onlyOwner.
        }

        vm.prank(nonOwner);
        try c.sendMoney{value: 0}(target, 0) returns () {
            // sendMoney succeeded - this means the buggy modifier let nonOwner through.
            // In reference, nonOwner would have been reverted by require(msg.sender==owner).
            // Therefore if this code is reached, depositsCount must have changed only if the fallback triggered
            // but we need to assert a property that holds for reference and fails for bug
        } catch {
            // sendMoney reverted - in reference this always happens for nonOwner;
            // in buggy it can succeed for nonOwner
        }

        // Assertion: after the above, depositsCount must have changed only if fallback was triggered AND sendMoney didn't revert.
        // Actually we need a universal property that reference satisfies and bug breaks.
        // Property: For any caller, if sendMoney does NOT revert, the caller MUST be the owner.
        // We check this by calling sendMoney as nonOwner; in reference it always reverts, so code after a non-reverting call is unreachable.
        // We can assert that calling sendMoney as nonOwner always reverts.
        bool sendMoneyReverted;
        vm.prank(nonOwner);
        try c.sendMoney(target, value) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }
        assertTrue(sendMoneyReverted);
    }
}

