contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 preBalance, uint256 caller) public {
        // Constrain fuzzed values to a wide admissible domain
        vm.assume(caller != address(0));
        vm.assume(preBalance >= 1 && preBalance < type(uint96).max);

        // Setup: fund the contract with a fuzzed balance
        vm.deal(address(c), preBalance);
        // The owner is the default EOA that deployed the contract (this contract)
        address originalOwner = c.owner();
        uint256 ownerBalanceBefore = originalOwner.balance;

        // Call withdrawAll from the owner
        vm.prank(originalOwner);
        bool ok = true;
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        require(ok, "withdrawAll reverted");

        uint256 contractBalanceAfter = address(c).balance;
        uint256 ownerBalanceAfter = originalOwner.balance;

        // The general rule: the contract's balance after must be zero
        // AND the owner's balance must increase by exactly (preBalance - contractBalanceAfter).
        // The buggy withdraw(0) breaks this because contractBalanceAfter == preBalance,
        // so the owner's balance doesn't increase (or increases by zero minus gas costs).
        // For the correct contract, contractBalanceAfter == 0, so ownerBalanceAfter = ownerBalanceBefore + preBalance.
        assertTrue(contractBalanceAfter == 0 && ownerBalanceAfter == ownerBalanceBefore + preBalance);
    }
}

